        "title": "简介",
        "body": "曹雪芹故居纪念馆位于北京市东城区广渠门内大街207号（蒜市口街16号），是伟大文学家曹雪芹晚年居住的地方。在这里，曹雪芹经历了从锦衣玉食到举家食粥的巨变，以\"字字看来皆是血，十年辛苦不寻常\"的精神，创作了中国古典小说的巅峰之作《红楼梦》。"
