        "body": "【曹家兴衰】\n\n曹雪芹（约1715-1763），名霑，字梦阮，号雪芹。其家族为清代内务府正白旗包衣出身，曾祖曹玺、祖父曹寅、父曹頫三代世袭江宁织造，家世显赫。康熙南巡时，曹家曾四次接驾，富贵至极。\n\n家道中落\n\n\n【蒜市口故居】\n\n乾隆年间，曹雪芹家从南京迁回北京后，居于崇文门外蒜市口一带。据考证，广渠门内大街207号院即为曹雪芹晚年居住地之一。此处靠近崇文门，交通便利，周边商业繁荣，是当年普通旗人居住的区域。"
