    "name": "颐和园",
    "categoryId": "landmarks",
    "summary": "\"虽由人作，宛自天开。\" —— 中国造园艺术的最高境界，颐和园正是其巅峰之作",
    "tags": [
      "名胜古迹"
    ],
    "cover": "https://images.unsplash.com/photo-1573657860396-d7b1656adc53?w=800",
    "featured": false,
