    "name": "圆明园",
    "categoryId": "landmarks",
    "summary": "\"有一天，两个强盗闯进了圆明园，一个强盗洗劫，另一个强盗放火……在历史面前，这两个强盗一个叫法兰西，一个叫英吉利。\" —— 维克多·雨果《就英法联军远征中国给巴特勒上尉的信》（1861年）",
