    "sections": [
      {
        "title": "简介",
        "body": "中国国家博物馆（简称国博）位于天安门广场东侧，是代表国家收藏、研究、展示、阐释中华文化代表性物证的最高历史文化艺术殿堂，也是世界上单体建筑面积最大的博物馆。国博现有藏品140余万件（套），涵盖古代文物、近现代文物、艺术品等多种门类。"
      },
      {
        "title": "历史沿革",
        "body": "【创建】\n\n中国国家博物馆的历史可追溯至1912年。时任教育总长蔡元培主持成立国立历史博物馆筹备处，这是中国第一个国立博物馆。\n\n【发展历程】\n\n- 1926年：国立历史博物馆正式开放\n- 1959年：中国历史博物馆和中国革命博物馆在天安门广场东侧建成\n- 2003年：中国历史博物馆和中国革命博物馆合并，组建中国国家博物馆\n- 2011年：新馆建成开放，成为世界上建筑面积最大的博物馆\n\n【新馆建设】\n\n2007年，国博启动改扩建工程。新馆由德国gmp建筑事务所设计，建筑面积近20万平方米，展厅面积约6.5万平方米，于2011年3月竣工开放。"
      },
      {
        "title": "建筑特色",
        "body": "【外观设计】\n\n国博新馆建筑由两部分组成：原有的历史博物馆建筑（1959年建成）和新建的北扩部分。建筑外观庄重大气，与天安门广场的整体风格协调统一。\n\n立面设计\n\n- 柱廊：入口有34根高大的廊柱\n- 墙面：浅黄色石材，庄重典雅\n- 屋顶：平顶设计，与人民大会堂遥相呼应\n\n【内部空间】\n\n国博内部空间宏大，展厅众多。主要展厅包括：\n\n- 中央大厅：高33米，面积2000平方米\n- 展厅：48个展厅，总面积6.5万平方米\n- 剧场：可容纳800人的剧场\n- 学术报告厅：用于学术交流活动"
      },
      {
        "title": "常设展览",
        "body": "【古代中国】\n\n「古代中国」是国博最重要的基本陈列，以王朝更替为主要脉络，展示从远古时期到清代的中国历史发展进程。\n\n展览内容\n\n\n镇馆之宝\n\n1. 后母戊鼎：商代青铜器，世界最大青铜器\n2. 四羊方尊：商代青铜器，工艺精湛\n3. 击鼓说唱俑：东汉陶俑，生动传神\n4. 金缕玉衣：汉代皇帝殓服\n\n【复兴之路】\n\n「复兴之路」展览展示1840年鸦片战争以来中国人民争取民族独立、人民解放和国家富强、人民幸福的历史进程。\n\n展览内容\n\n- 鸦片战争与近代中国的沉沦\n- 辛亥革命与君主专制的终结\n- 中国共产党的成立\n- 抗日战争\n- 新中国的成立\n- 社会主义建设\n- 改革开放\n\n【专题展览】"
      },
      {
        "title": "镇馆之宝详解",
        "body": "【后母戊鼎（商代）】\n\n后母戊鼎（原称司母戊鼎）是商王祖庚或祖甲为祭祀其母戊所制，是世界迄今出土最大、最重的青铜器，享有\"镇国之宝\"的美誉。鼎高133厘米、口长110厘米、口宽79厘米，重832.84公斤。\n\n【四羊方尊（商代）】\n\n四羊方尊是商代晚期青铜礼器，祭祀用品。尊四角各塑一羊，羊首与羊颈伸出器外，羊身与羊腿附着于尊腹部及圈足上。方尊肩饰高浮雕蛇身龙纹，工艺精湛。\n\n【击鼓说唱俑（东汉）】\n\n击鼓说唱俑出土于四川成都天回山崖墓，高55厘米。俑袒胸露腹，着裤赤足，左臂挟鼓，右手举槌，笑容满面，神态生动，是汉代陶俑艺术的巅峰之作。"
      },
      {
        "title": "游览攻略",
        "body": "【预约须知】\n\n1. 提前预约：必须提前1-7天在国博官网、微信公众号或APP预约\n2. 身份证件：入场需携带预约时使用的身份证原件\n3. 安检严格：禁止携带打火机等违禁物品\n4. 限流措施：国博每日限流，建议提前预约\n\n【推荐路线】\n\n半日游路线（约4小时）：\n\n北门入口 → 古代中国展厅（远古→夏商周→秦汉） → 镇馆之宝 → 复兴之路展厅 → 中央大厅 → 专题展览 → 文创商店 → 南门出口\n\n一日游路线（约6-8小时）：\n\n北门入口 → 古代中国展厅（完整游览） → 午餐（国博餐厅） → 复兴之路展厅 → 青铜器专题展 → 瓷器专题展 → 玉器专题展 → 书画展 → 文创商店 → 天安门广场\n\n【实用贴士】\n\n1. 最佳时间：周二至周四人相对较少\n2. 讲解服务：可租借语音导览器（押金200元，租金10元），或参加免费讲解\n3. 餐饮服务：地下一层有餐厅，价格适中\n4. 文创商店：国博文创很有特色，可购买纪念品\n5. 拍照注意：部分展品禁止拍照，注意标识\n6. 存包服务：大件行李需寄存（免费）\n\n【周边游览】"
      },
      {
        "title": "文化意义",
        "body": "中国国家博物馆是国家最高历史文化艺术殿堂，是中华文明的集中展示。正如习近平总书记所说：\n\n\"博物馆是保护和传承人类文明的重要殿堂，是连接过去、现在、未来的桥梁。\"\n\n国博不仅展示中华文明的灿烂成就，也承载着民族复兴的历史记忆，是了解中国历史文化的必到之处。\n\n📍 地址：北京市东城区东长安街16号\n📞 电话：010-65116400\n🌐 官网：www.chnmuseum.cn\n📱 预约：关注「国家博物馆」微信公众号预约"
      }
    ]
