        "body": "【始建】\n\n明嘉靖九年（1530年），明世宗朱厚熜决定实行天地分祀，在北京东郊建日坛，专祀太阳神。\n\n【清代修缮】\n\n清代，日坛多次修缮，规模不断扩大。\n\n【现代公园】\n\n1950年代，日坛辟为公园，对外开放。现为日坛公园。"
