    "sections": [
      {
        "title": "简介",
        "body": "玉渊潭公园位于北京市海淀区，是北京最大的樱花观赏地，也是北京著名的城市公园。公园占地约137公顷，其中水面约60公顷，是北京三环内最大的公园。"
      },
      {
        "title": "历史沿革",
        "body": "【辽金时期】\n\n玉渊潭地区在辽金时期就是著名的风景区，\"玉渊潭\"之名始见于金代。\n\n【清代行宫】\n\n清代，乾隆皇帝在此修建行宫，是皇帝游幸之地。\n\n【现代公园】\n\n1960年，玉渊潭正式辟为公园，对外开放。"
      },
      {
        "title": "园区布局",
        "body": "玉渊潭公园分为东湖、西湖、南湖三个湖区。\n\n【东湖】\n\n东湖是玉渊潭公园的主要景区，有樱花园、湿地园等。\n\n樱花园\n\n樱花园位于东湖湖畔，是北京最大的樱花园。\n\n\n樱花品种\n\n\n【西湖】\n\n西湖有游船码头，可以划船游湖。\n\n【南湖】\n\n南湖人较少，比较安静。"
      },
      {
        "title": "樱花节",
        "body": "玉渊潭公园每年春季举办樱花节，是北京著名的花事活动。\n\n【举办时间】\n\n每年3月下旬至4月中旬，根据花期调整。\n\n【活动内容】\n\n- 赏樱：观赏各种樱花\n- 摄影比赛：樱花摄影比赛\n- 文化活动：樱花文化展览\n- 美食：樱花主题美食\n\n【门票】\n\n樱花节期间门票10元（平时2元）。"
      },
      {
        "title": "电视塔倒影",
        "body": "玉渊潭公园的标志性景观是中央电视塔的倒影。\n\n【最佳拍摄点】\n\n- 东湖湖畔：可以拍到电视塔在湖中的倒影\n- 傍晚时分：夕阳西下，景色最美\n\n【拍摄建议】\n\n天气晴好时，湖面平静，倒影清晰，是拍摄的最佳时机。"
      },
      {
        "title": "游览攻略",
        "body": "【推荐路线】\n\n经典路线（约2-3小时）：\n\n南门 → 东湖樱花园 → 西湖游船 → 电视塔倒影 → 北门\n\n樱花节路线：\n\n西门 → 樱花园（赏樱） → 东湖湖畔 → 南门\n\n【交通方式】\n\n\n【实用贴士】\n\n1. 樱花最佳时间：3月下旬至4月中旬\n2. 避开人流：早上7:00前或下午4:00后人较少\n3. 樱花节门票：樱花节期间门票10元\n4. 划船体验：可以划船游湖\n5. 拍照建议：下午3:00-5:00光线最佳\n6. 结合游览：可与军事博物馆、首博一起游览"
      },
      {
        "title": "周边景点",
        "body": "📍 地址：北京市海淀区西三环中路10号\n📞 电话：010-88653800"
      }
    ]
