        "body": "东堂，又称王府井天主堂、圣若瑟堂，位于北京市东城区王府井大街74号，是北京四大天主教堂之一。教堂始建于清顺治十二年（1655年），是罗马式建筑风格的典范，也是王府井地区的重要地标。"
